% Filter BW to match Signal BW
MaxPosFF = ((Nt/2)-1)*dF;
MaxNegFF = (-(Nt/2))*dF;

% Filter BW in 40 MHz steps
FiltBW = MaxNegFF:40e6:MaxPosFF;
Lbw = length(FiltBW);

% Length of frequency responce
Lf = length(FreqRespdB);

% Two sided frequency responce
hh = FreqRespdB(end).*ones(size(FiltBW));
hh(1) = FreqRespdB(1);

if length(FiltBW)/2 <= Lf
    % Truncate the Frequency responce before interpolating
    % for Signal BW of less than 20 Ghz;
    hh(2:2+Lbw/2-1) = FreqRespdB(1:Lbw/2);    
    hh(end-Lbw/2+1:end) = fliplr(FreqRespdB(1:Lbw/2));
else
    hh(2:2+Lf-1) = FreqRespdB;
    hh(end-Lf+1:end) = fliplr(FreqRespdB);
end

% Interpolate hh to match number of points in Nt
hh = interpft(hh,Nt);

% Plot the frequency responce
% figure(13);
% plot(fftshift(FF), fftshift(hh));

% Convert to freq responce to linear
hh = ones(Np,1)*10.^(hh/20);

% figure(11);
% plot(fftshift(FF), fftshift(hh)); grid on;

% Apply the filter
